const o=i=>{const e=i[0],n={thing:e.dataset.thing,CRAFT_CSRF_TOKEN:window.csrfTokenValue};fetch("/get-edit-link",{headers:{"X-Requested-With":"XMLHttpRequest","Content-Type":"application/json"},method:"POST",body:JSON.stringify(n)}).then(t=>t.text()).then(t=>{t&&t.trim()&&(e.innerHTML=t,setTimeout(function(){document.querySelector(".edit-this").classList.remove("posing")},600))})};export{o as default};
